mapper.select:
SELECT ,
       rp.RECEIPT_NO, rv.DOCUMENT_NO, c.CUSTOMER_NAME
FROM TBL_AR_WRITE_OFF w
LEFT JOIN TBL_AR_RECEIPT rp ON w.RECEIPT_ID = rp.RECEIPT_ID AND rp.IS_DELETED = 0
LEFT JOIN TBL_AR_RECEIVABLE rv ON w.RECEIVABLE_ID = rv.RECEIVABLE_ID AND rv.IS_DELETED = 0
LEFT JOIN TBL_AR_CUSTOMER c ON rp.CUSTOMER_ID = c.CUSTOMER_ID AND c.IS_DELETED = 0
WHERE w.IS_DELETED = 0

    AND w.RECEIPT_ID = #{param.receiptId}


    AND w.RECEIVABLE_ID = #{param.receivableId}


    AND rp.CUSTOMER_ID = #{param.customerId}


    AND w.WRITE_OFF_TYPE = #{param.writeOffType}


    AND w.WRITE_OFF_DATE >= #{param.writeOffDateStart}


    AND w.WRITE_OFF_DATE <= #{param.writeOffDateEnd}


    AND w.TENANT_ID = #{param.tenantId}


    AND w.ORG_ID = #{param.orgId}

ORDER BY w.CREATE_TIME DESC

SELECT , rp.RECEIPT_NO, rv.DOCUMENT_NO, c.CUSTOMER_NAME FROM TBL_AR_WRITE_OFF w LEFT JOIN TBL_AR_RECEIPT rp ON w.RECEIPT_ID = rp.RECEIPT_ID AND rp.IS_DELETED = 0 LEFT JOIN TBL_AR_RECEIVABLE rv ON w.RECEIVABLE_ID = rv.RECEIVABLE_ID AND rv.IS_DELETED = 0 LEFT JOIN TBL_AR_CUSTOMER c ON rp.CUSTOMER_ID = c.CUSTOMER_ID AND c.IS_DELETED = 0 WHERE w.IS_DELETED = 0
AND w.TENANT_ID = #{param.tenantId}
ORDER BY w.CREATE_TIME DESC
